<?php
 namespace QQWorld\Catalog\Test\Constraint; use QQWorld\Catalog\Test\Fixture\CatalogProductAttribute; use QQWorld\Catalog\Test\Page\Category\CatalogCategoryView; use QQWorld\Cms\Test\Page\CmsIndex; use QQWorld\Mtf\Constraint\AbstractConstraint; use QQWorld\Mtf\Fixture\InjectableFixture; class AssertProductAttributeIsFilterableInSearch extends AbstractConstraint { public function processAssert( CmsIndex $cmsIndex, CatalogCategoryView $catalogCategoryView, InjectableFixture $product, CatalogProductAttribute $attribute ) { $cmsIndex->open()->getSearchBlock()->search($product->getName()); $label = $attribute->hasData('manage_frontend_label') ? $attribute->getManageFrontendLabel() : $attribute->getFrontendLabel(); \PHPUnit_Framework_Assert::assertTrue( in_array(strtoupper($label), $catalogCategoryView->getLayeredNavigationBlock()->getFilters()), 'Attribute is absent in layered navigation on search page.' ); } public function toString() { return 'Attribute is present in layered navigation on search page.'; } } 